IF NOT EXISTS (SELECT 1 FROM [scenario].[KnowledgeItems] WHERE [ScenarioVersionId] = @ScenarioVersionId_OMNI_001_V1 AND [Code] = N'K-IT-03')
BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_OMNI_001_V1, N'K-IT-03', N'Cơ chế dự phòng khi đứt cáp hoặc mất mạng internet cửa hàng', N'Nếu cửa hàng mất kết nối internet, máy POS vẫn cho phép nhân viên thu ngân quét mã vạch và thanh toán tiền mặt (offline mode).

Tuy nhiên, toàn bộ giao dịch offline sẽ không trừ tồn kho hệ sinh thái OmniMart ngay lập tức. Khi có mạng trở lại, hàng chục đơn hàng sẽ dồn về cùng lúc (surge sync), dễ gây ra hiện tượng âm kho (negative inventory) nếu trên kênh online cùng lúc đó có khách đặt mua đúng mặt hàng đó.', N'System', N'High', SYSDATETIMEOFFSET());
END;
