BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_OMNI_001_V1, N'K-IT-04', N'Giới hạn lưu lượng và khả năng mở rộng của Database trung tâm', N'Cơ sở dữ liệu ERP hiện tại sử dụng công nghệ cũ và đang chịu tải phục vụ đồng thời cho kế toán, kho và 25 chi nhánh.

Ngưỡng chịu tải tối đa là 350 TPS (transactions per second). Nếu nâng tần suất đồng bộ từ POS lên real-time, nguy cơ nghẽn kết nối (connection pool exhaustion) là rất cao, dẫn tới treo toàn bộ hệ thống hóa đơn điện tử.', N'System', N'Medium', SYSDATETIMEOFFSET());
END;
