IF NOT EXISTS (SELECT 1 FROM [scenario].[KnowledgeItems] WHERE [ScenarioVersionId] = @ScenarioVersionId_OMNI_001_V1 AND [Code] = N'K-OPS-02')
BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_OMNI_001_V1, N'K-OPS-02', N'Hạn mức phê duyệt hoàn tiền', N'Hoàn tiền tại OmniMart được phê duyệt theo giá trị đơn:

- Dưới 500.000 đồng: trưởng ca tại cửa hàng được phê duyệt ngay.
- Từ 500.000 đến dưới 2.000.000 đồng: cần Store Manager phê duyệt.
- Từ 2.000.000 đồng trở lên: cần Finance phê duyệt, thường mất 1 đến 3 ngày làm việc.

Đội vận hành muốn trưởng ca được tự hoàn tiền tới 2.000.000 đồng để giải quyết khiếu nại nhanh, nhưng Finance chưa đồng ý vì lo rủi ro gian lận. Chính sách này chưa được ghi thành văn bản chính thức, mỗi cửa hàng áp dụng hơi khác nhau.', N'Policy', N'Critical', SYSDATETIMEOFFSET());
END;
