IF NOT EXISTS (SELECT 1 FROM [scenario].[KnowledgeItems] WHERE [ScenarioVersionId] = @ScenarioVersionId_OMNI_001_V1 AND [Code] = N'K-OPS-03')
BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_OMNI_001_V1, N'K-OPS-03', N'Thời gian giữ đơn và quy trình xử lý đơn COD chưa giao', N'Với các đơn hàng chọn hình thức thanh toán khi nhận hàng (COD):
1. Nhân viên CSKH sẽ gọi điện xác nhận đơn tối đa 3 lần trong vòng 24 giờ kể từ lúc đặt đơn.
2. Nếu sau 3 lần không liên lạc được hoặc khách báo hủy, đơn sẽ chuyển sang trạng thái "Chờ hủy".
3. Hàng giữ trong kho sẽ được tự động giải phóng (trả về tồn khả dụng) sau đúng 48 giờ kể từ lúc tạo đơn nếu không được xác nhận.

Khó khăn: Nhiều trường hợp nhân viên kho quên cập nhật thủ công trạng thái "Hủy", khiến hàng tồn thực tế bị đóng băng ảo trên hệ thống cả tuần.', N'Process', N'Medium', SYSDATETIMEOFFSET());
END;
